package com.bank.compliance;

import java.util.*;
import java.util.logging.*;

public class ComplianceDemo {
    private static final Logger log = Logger.getLogger("Compliance");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> batch = List.of(
            new Employee("Rajesh", 35, 1200000, "Trading"),
            new Employee("Priya", 30, 900000, "Risk"),
            new Employee("Amit", 28, 700000, "Settlement"));
        Set<String> blocked = Set.of("Sanctions", "Shell");
        ComplianceGate gate = new ComplianceGate();

        log.info(() -> "Any high earner (>1M): " + gate.hasHighEarner(batch, 1_000_000));
        log.info(() -> "All adults (>=18): " + gate.allAdults(batch));
        log.info(() -> "None from blocked dept: " + gate.noneFromBlocked(batch, blocked));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name; private final int age;
    private final double salary; private final String department;
    Employee(String name, int age, double salary, String department) {
        this.name = name; this.age = age; this.salary = salary; this.department = department;
    }
    int getAge() { return age; }
    double getSalary() { return salary; }
    String getDepartment() { return department; }
}

// ─── Would be in service/ComplianceGate.java ───
class ComplianceGate {
    boolean hasHighEarner(List<Employee> emps, double threshold) {
        return emps.stream().anyMatch(e -> e.getSalary() > threshold); // stops at first match
    }
    boolean allAdults(List<Employee> emps) {
        return emps.stream().allMatch(e -> e.getAge() >= 18);          // stops at first mismatch
    }
    boolean noneFromBlocked(List<Employee> emps, Set<String> blocked) {
        return emps.stream().noneMatch(e -> blocked.contains(e.getDepartment())); // stops at first hit
    }
}
